```
import { app, job } from "@wasp.sh/spec"
import { mySpecialJob } from "./src/workers/bar" with { type: "ref" }
export default app({
// ...
spec: [
job(mySpecialJob, {
executor: "PgBoss",
schedule: {
cron: "0 * * * *",
args: { name: "Johnny" }, // optional
},
}),
],
})

